	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "blog-post":
		return t.AsTimelineEntryBlogPost()
	case "follow":
		return t.AsTimelineEntryFollow()
	case "forum-post":
		return t.AsTimelineEntryForumPost()
	case "game-end":
		return t.AsTimelineEntryGameEnd()
	case "plan-renew":
		return t.AsTimelineEntryPlanRenew()
	case "plan-start":
		return t.AsTimelineEntryPlanStart()
	case "simul-create":
		return t.AsTimelineEntrySimul()
	case "simul-join":
		return t.AsTimelineEntrySimul()
	case "stream-start":
		return t.AsTimelineEntryStreamStart()
	case "study-like":
		return t.AsTimelineEntryStudyLike()
	case "team-create":
		return t.AsTimelineEntryTeamCreate()
	case "team-join":
		return t.AsTimelineEntryTeamJoin()
	case "tour-join":
		return t.AsTimelineEntryTourJoin()
	case "ublog-post":
		return t.AsTimelineEntryUblogPost()
	case "ublog-post-like":
		return t.AsTimelineEntryUblogPostLike()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
